<script setup>
import { computed, onMounted, ref } from 'vue'
import ListView from '../shared/components/ListView.vue'

const props = defineProps({ token: { type: String, required: true } })
const loading = ref(true); const saving = ref(false); const error = ref(''); const notice = ref('')
const catalog = ref({ services: [], consultationTypes: [], experts: [], allExperts: [] })
const formOpen = ref(false); const editingId = ref('')
const form = ref({ code: '', name: '', description: '', serviceCode: '', amountCents: 0, currency: 'USD', paymentRequired: true, active: true, expertIds: [] })
const consultations = computed(() => catalog.value.consultationTypes || [])
const assignedExperts = computed(() => catalog.value.experts || [])

async function request(url, options = {}) { const response = await fetch(url, { ...options, headers: { Authorization: `Bearer ${props.token}`, ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || 'No se pudo completar la operación.'); return data }
async function load() { loading.value = true; error.value = ''; try { catalog.value = await request('/api/app/catalog') } catch (loadError) { error.value = loadError.message } finally { loading.value = false } }
function openNew() { editingId.value = ''; form.value = { code: '', name: '', description: '', serviceCode: catalog.value.services[0]?.code || '', amountCents: 0, currency: 'USD', paymentRequired: true, active: true, expertIds: [] }; formOpen.value = true }
function edit(item) { const service = catalog.value.services.find((candidate) => candidate.consultations?.some((consultation) => consultation.consultationId === item.id)); const linked = assignedExperts.value.filter((expert) => expert.consultationTypeId === item.id).map((expert) => expert.id); const price = service?.consultations?.find((consultation) => consultation.consultationId === item.id); form.value = { code: item.code, name: item.name, description: item.description || '', serviceCode: service?.code || '', amountCents: price?.amountCents || 0, currency: price?.currency || 'USD', paymentRequired: true, active: item.active, expertIds: linked }; editingId.value = item.id; formOpen.value = true }
function cancel() { formOpen.value = false; editingId.value = '' }
async function save() { saving.value = true; error.value = ''; notice.value = ''; try { await request(editingId.value ? `/api/app/catalog/consultation-types/${editingId.value}` : '/api/app/catalog/consultation-types', { method: editingId.value ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form.value) }); notice.value = 'Tipo de consulta guardado correctamente.'; cancel(); await load() } catch (saveError) { error.value = saveError.message } finally { saving.value = false } }
function money(cents, currency) { return new Intl.NumberFormat('es-CO', { style: 'currency', currency, maximumFractionDigits: 0 }).format(Number(cents || 0) / 100) }
onMounted(load)
</script>

<template>
  <section class="module-view catalog-view"><div class="module-heading"><div><p class="eyebrow">Configuración operativa</p><h1>Servicios y consultas</h1><p>Administra la oferta comercial, sus precios y los expertos asignados.</p></div><div class="module-heading-actions"><button type="button" class="primary-button compact" @click="openNew">+ Nueva consulta</button><button type="button" class="secondary-button compact" @click="load">↻ Actualizar</button></div></div><p v-if="notice" class="security-notice">{{ notice }}</p><p v-if="error" class="request-error">{{ error }}</p><div v-if="loading" class="module-state panel">Cargando catálogo…</div><template v-else>
    <form v-if="formOpen" class="panel catalog-editor-form" @submit.prevent="save"><div class="panel-heading"><div><h2>{{ editingId ? 'Editar tipo de consulta' : 'Nueva consulta' }}</h2><p>Define el servicio general, precio, descripción y expertos.</p></div><button type="button" class="secondary-button compact" @click="cancel">Cancelar</button></div><div class="catalog-form-grid"><label>Código<input v-model="form.code" :disabled="Boolean(editingId)" pattern="[a-z][a-z0-9_-]{2,50}" placeholder="consulta_basica" required /></label><label>Servicio general<select v-model="form.serviceCode" required><option value="" disabled>Selecciona un servicio</option><option v-for="service in catalog.services" :key="service.id" :value="service.code">{{ service.name }}</option></select></label><label>Nombre<input v-model="form.name" placeholder="Consulta básica" required /></label><label>Precio<input v-model.number="form.amountCents" type="number" min="0" step="1" required /></label><label>Moneda<select v-model="form.currency"><option value="USD">USD</option><option value="COP">COP</option></select></label><label class="full-label">Descripción<textarea v-model="form.description" rows="3" placeholder="Describe qué incluye la consulta." required></textarea></label></div><fieldset class="permission-picker"><legend>Expertos asociados</legend><label v-for="expert in catalog.allExperts" :key="expert.id" class="permission-option"><input v-model="form.expertIds" type="checkbox" :value="expert.id" /><span><strong>{{ expert.name }}</strong><small>{{ expert.email }}</small></span></label><small v-if="!catalog.allExperts?.length" class="empty-inline">Primero crea usuarios con rol Experto.</small></fieldset><div class="form-actions"><button type="button" class="secondary-button compact" @click="cancel">Cancelar</button><button type="submit" class="primary-button" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar consulta' }} <span>→</span></button></div></form>
    <ListView title="Tipos de consulta" description="Servicios vendibles con precio y expertos responsables." :count="consultations.length" :page="1" :total-pages="1" :empty="!consultations.length" empty-text="No hay tipos de consulta configurados."><template #columns><th>Consulta</th><th>Servicio general</th><th>Precio</th><th>Expertos</th><th>Estado</th><th>Acciones</th></template><template #rows><tr v-for="item in consultations" :key="item.id"><td><strong>{{ item.name }}</strong><br /><span class="muted-cell">{{ item.description }}</span></td><td>{{ catalog.services.find((service) => service.consultations?.some((consultation) => consultation.consultationId === item.id))?.name || '—' }}</td><td>{{ money(catalog.services.flatMap((service) => service.consultations || []).find((consultation) => consultation.consultationId === item.id)?.amountCents, catalog.services.flatMap((service) => service.consultations || []).find((consultation) => consultation.consultationId === item.id)?.currency || 'USD') }}</td><td><span class="count-badge">{{ assignedExperts.filter((expert) => expert.consultationTypeId === item.id).length }}</span></td><td><span :class="['security-status', { inactive: !item.active }]">{{ item.active ? 'Activo' : 'Inactivo' }}</span></td><td><button type="button" class="secondary-button compact" @click="edit(item)">Editar</button></td></tr></template></ListView>
    <ListView title="Servicios generales" description="Clasificación principal de la operación aduanera." :count="catalog.services.length" :page="1" :total-pages="1" :empty="!catalog.services.length" empty-text="No hay servicios configurados."><template #columns><th>Servicio</th><th>Descripción</th><th>Consultas</th><th>Estado</th></template><template #rows><tr v-for="service in catalog.services" :key="service.id"><td><strong>{{ service.name }}</strong></td><td>{{ service.description || 'Sin descripción' }}</td><td><span class="count-badge">{{ service.consultations?.length || 0 }}</span></td><td><span :class="['security-status', { inactive: !service.active }]">{{ service.active ? 'Activo' : 'Inactivo' }}</span></td></tr></template></ListView>
  </template></section>
</template>

<style scoped>
.catalog-editor-form{display:grid;gap:16px;margin-bottom:16px;padding:20px;border:1px solid #e5eaf0;border-radius:10px;background:#fff;box-shadow:0 4px 12px rgba(25,47,70,.025)}.catalog-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.catalog-form-grid label{display:grid;gap:7px;color:#526174;font-size:10px;font-weight:700}.catalog-form-grid input,.catalog-form-grid select,.catalog-form-grid textarea{min-height:38px;padding:8px 10px;border:1px solid #d8e0ea;border-radius:7px;color:#344b60;background:#fff;font-size:11px}.catalog-form-grid textarea{resize:vertical}.catalog-editor-form .permission-picker{margin:0}.form-actions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:800px){.catalog-form-grid{grid-template-columns:1fr}}
</style>
